    },
    {
      "category": "wrong_value",
      "components": ["C2"],
      "pins": ["C2.1", "C2.2"],
      "nets": ["+5V", "GND"],
      "observed": "C2 is a 100 nF capacitor on the +5V output of the LM1117-5.0 regulator.",
      "expected": "The LM1117 datasheet requires a minimum output capacitance of 10 µF for stability.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"C2\") (value \"100nF\") (footprint \"Capacitor_SMD:C_0805_2012Metric\")"
        },
        {
          "source": "netlist",
          "quote": "(comp (ref \"U1\") (value \"LM1117-5.0\") (footprint \"Package_TO_SOT_SMD:SOT-223-3_TabPin2\") (datasheet \"http://www.ti.com/lit/ds/symlink/lm1117.pdf\")"
        }
      ],
      "impact": "The regulator may oscillate or be unstable, causing an unstable 5V rail and erratic operation of the ATtiny microcontrollers and other 5V circuitry.",
      "confidence": 0.85
    }
